package com.aliothmoon.maafw.once;
import org.junit.Test;
import static org.junit.Assert.*;
import java.nio.file.*;
import java.util.*;
public class RootReturnReadScopeTest {
 @Test public void exactlyThreeIndependentReadSlots(){assertTrue(RootReturnReadScope.ACTIVE);assertEquals(3,RootReturnReadScope.MAX_FRAMES);assertEquals(15,RootReturnReadScope.SOURCE_TASK_ID);Set<String> slots=new HashSet<>();for(int i=1;i<=3;i++)assertTrue(slots.add(RootReturnReadScope.slot(i)));assertEquals(Set.of("READ_1","READ_2","READ_3"),slots);for(int i:new int[]{-1,0,4,Integer.MAX_VALUE})assertThrows(SecurityException.class,()->RootReturnReadScope.slot(i));}
 @Test public void original180sAdmission(){long s=RootReturnReadScope.STARTS_UTC,e=RootReturnReadScope.EXPIRES_UTC;assertFalse(RootReturnReadScope.current(s-1));assertTrue(RootReturnReadScope.current(s));assertFalse(RootReturnReadScope.current(e));assertTrue(RootReturnReadScope.admissionCurrent(e-180001));assertFalse(RootReturnReadScope.admissionCurrent(e-180000));assertEquals(181000,RootReturnReadScope.sessionDeadline(1000,s));}
 @Test public void readDeadlineCannotExtendParentOrWindow(){long u=RootReturnReadScope.STARTS_UTC;assertEquals(91000,RootReturnReadScope.deadline(1000,u,181000));assertEquals(1500,RootReturnReadScope.deadline(1000,u,1500));assertEquals(1001,RootReturnReadScope.deadline(1000,RootReturnReadScope.EXPIRES_UTC-1,181000));}
 @Test public void invalidTimesFailClosed(){long u=RootReturnReadScope.STARTS_UTC;assertThrows(SecurityException.class,()->RootReturnReadScope.sessionDeadline(-1,u));assertThrows(SecurityException.class,()->RootReturnReadScope.sessionDeadline(Long.MAX_VALUE,u));assertThrows(SecurityException.class,()->RootReturnReadScope.deadline(1,u,1));assertThrows(SecurityException.class,()->RootReturnReadScope.deadline(-1,u,100));assertThrows(SecurityException.class,()->RootReturnReadScope.deadline(Long.MAX_VALUE,u,Long.MAX_VALUE));}
 @Test public void namespaceNeverReusesV31(){assertNotEquals(RootBoundedBusinessScope.DIRECTORY,RootReturnReadScope.DIRECTORY);assertNotEquals(RootImageSeriesScope.DIRECTORY,RootReturnReadScope.DIRECTORY);assertThrows(SecurityException.class,()->RootReturnReadScope.store(null,1));assertThrows(SecurityException.class,()->RootReturnReadScope.burnReturn(null,"safe"));}
 @Test public void invalidMetadataBeforeAnyWrite()throws Exception{var st=RootReturnReadScope.store(Path.of("unused"),1);assertThrows(SecurityException.class,()->st.burn("invalid","safe"));assertThrows(SecurityException.class,()->st.burn("11111111-1111-1111-1111-111111111111",null));assertThrows(SecurityException.class,()->st.burn("11111111-1111-1111-1111-111111111111","x".repeat(2049)));assertThrows(SecurityException.class,()->RootReturnReadScope.burnReturn(Path.of("unused"),null));}
 @Test public void durableFixedReturnNoTapOrRecoveryPrimitive()throws Exception{Path p=Path.of("../app/src/main/java/com/aliothmoon/maafw/once/RootReturnReadScope.java");if(!Files.exists(p))p=Path.of("app/src/main/java/com/aliothmoon/maafw/once/RootReturnReadScope.java");String s=Files.readString(p);assertTrue(s.contains("StandardOpenOption.CREATE_NEW"));assertTrue(s.contains("c.force(true)"));assertTrue(s.contains("burn(files,\"RETURN\""));assertFalse(s.contains("burnAction"));assertFalse(s.contains("delete("));assertFalse(s.contains("TRUNCATE_EXISTING"));assertTrue(s.contains("maxFrames=3 maxTap=0 maxReturn=1"));}
}
